from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1];state={'selected':'2026-10-31','requests':[]}
html='''<meta charset="utf-8"><select id="scheduleSource"><option value="naqar">نقار</option><option value="madrasati">مدرستي</option></select><label id="madrasatiDateLabel"><input id="madrasatiSourceDate" type="date"></label><p id="madrasatiDateHint"></p><button id="collectMadrasati">نقل</button><p id="scheduleSourceStatus"></p><script>chrome={storage:{local:{set:values=>window.saveDate(values)}},runtime:{sendMessage:async m=>{if(m.type==='MIRSAD_SOURCE_COLLECT'){await window.recordRequest(m);return {ok:true}}return window.sourceInfo()}}}</script><script src="/madrasati-ui.js"></script>'''
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);context=b.new_context();context.expose_binding('saveDate',lambda source,values:state.update(selected=values['mirsadMadrasatiSelectedDate']));context.expose_binding('recordRequest',lambda source,m:state['requests'].append(m));context.expose_binding('sourceInfo',lambda source:{'ok':True,'mode':'madrasati','selectedDate':state['selected'],'state':{'running':False,'text':'تم إرسال 0 حصة · 2026-10-31'},'lastSuccess':{'date':'2026-10-31','lessons':0}})
 context.route('**/*',lambda r:r.fulfill(content_type='text/html',body=html) if r.request.url.endswith('/') else r.fulfill(path=str(R/'teams-probe/madrasati-ui.js')))
 page=context.new_page();page.goto('https://popup.local/');page.wait_for_function("document.getElementById('madrasatiSourceDate').value==='2026-10-31'");page.locator('#madrasatiSourceDate').fill('2026-10-18');page.close()
 page=context.new_page();page.goto('https://popup.local/');page.wait_for_function("document.getElementById('madrasatiSourceDate').value==='2026-10-18'");assert state['selected']=='2026-10-18';text=page.locator('#scheduleSourceStatus').inner_text();assert '2026-10-18' in text and '2026-10-31' in text
 page.locator('#madrasatiSourceDate').fill('2026-10-19');page.locator('#collectMadrasati').click();page.wait_for_function("document.getElementById('scheduleSourceStatus').textContent.includes('بدأ جمع')");assert state['requests'][-1]['date']=='2026-10-19';page.close();page=context.new_page();page.goto('https://popup.local/');page.wait_for_function("document.getElementById('madrasatiSourceDate').value==='2026-10-19'");b.close();print('PASS date saved before collect, immediate popup close/reopen, selected date reaches collect request, previous success labeled separately')
